B-1：题词卡结构重新分区
当前问题： AnswerCueCard 的字段（开场句、要点、可引用证据、风险提醒、可能追问）全部等权重平铺，面试时没有视觉焦点。
要做的改动：
1. 找到渲染 AnswerCueCard 的 JSX 区块（大约在 live.tsx 的 CueCard 或类似组件），按以下优先级重新分区：
function CueCard({ card }: { card: AnswerCueCard }) {
  return (
    <div className="cue-card">
      {/* 区块 1：开场句 —— 最大字号，最顶部，蓝色强调 */}
      {card.opener && (
        <div className="cue-opener">
          <div className="cue-section-label">开场句</div>
          <p className="cue-opener-text">{card.opener}</p>
        </div>
      )}

      {/* 区块 2：核心要点 —— 编号列表，最多 3 条 */}
      {card.keyPoints && card.keyPoints.length > 0 && (
        <div className="cue-section">
          <div className="cue-section-label">核心要点</div>
          <ol className="cue-points">
            {card.keyPoints.slice(0, 3).map((pt, i) => (
              <li key={i} className="cue-point-item">{pt}</li>
            ))}
          </ol>
        </div>
      )}

      {/* 区块 3：可引用证据 —— 折叠展示，默认展开 1 条 */}
      {card.evidence && card.evidence.length > 0 && (
        <details className="cue-evidence" open>
          <summary className="cue-section-label">证据 · {card.evidence.length} 条</summary>
          <ul className="cue-evidence-list">
            {card.evidence.map((ev, i) => (
              <li key={i}>{ev}</li>
            ))}
          </ul>
        </details>
      )}

      {/* 区块 4：风险提醒 —— 橙色警示色，放最后 */}
      {card.risks && card.risks.length > 0 && (
        <div className="cue-risks">
          <div className="cue-section-label cue-section-label--warn">⚠ 注意</div>
          {card.risks.map((r, i) => (
            <p key={i} className="cue-risk-item">{r}</p>
          ))}
        </div>
      )}

      {/* 区块 5：可能追问 —— 最小，置底 */}
      {card.followUps && card.followUps.length > 0 && (
        <div className="cue-followups">
          <div className="cue-section-label">可能追问</div>
          <ul>
            {card.followUps.map((q, i) => (
              <li key={i} className="cue-followup-item">{q}</li>
            ))}
          </ul>
        </div>
      )}

      {/* AI / 本地模式标记 */}
      <div className="cue-meta">
        {card.aiRunMeta?.backendStatus === 'ok' ? '模型生成' : `本地练习 · ${card.aiRunMeta?.fallbackReason ?? ''}`}
        {card.aiRunMeta?.latencyMs && ` · ${card.aiRunMeta.latencyMs}ms`}
      </div>
    </div>
  );
}
