function NextStepSuggestion({ record }: { record: InterviewRecord }) {
  // 从 record 中分析薄弱题型
  // 假设 record 中有 questionResults: Array<{ type: string; score: number; question: string }>
  const weakTypes = getWeakTypes(record);  // 见下方实现

  return (
    <div className="next-step-card">
      <div className="next-step-header">
        <span className="next-step-title">📌 下次练习建议</span>
      </div>
      {weakTypes.length === 0 ? (
        <p className="next-step-empty">本次表现不错，继续保持！</p>
      ) : (
        <>
          <p className="next-step-desc">
            根据本次记录，以下类型的题目表现偏弱，建议优先练习：
          </p>
          <div className="weak-type-list">
            {weakTypes.slice(0, 3).map((wt, i) => (
              <div key={i} className="weak-type-item">
                <div className="weak-type-info">
                  <span className="weak-rank">#{i + 1}</span>
                  <div>
                    <span className="weak-name">{wt.label}</span>
                    <span className="weak-score">平均得分 {wt.avgScore}%</span>
                  </div>
                </div>
                <button
                  className="btn-practice"
                  onClick={() => {
                    // 跳转到模拟面试并预设题型过滤
                    dispatch({ type: 'START_MOCK', filter: wt.type });
                  }}
                >
                  去练习 →
                </button>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// 薄弱题型计算辅助函数
function getWeakTypes(record: InterviewRecord) {
  if (!record.questionResults) return [];
  const typeMap: Record<string, { total: number; count: number; label: string }> = {};
  for (const qr of record.questionResults) {
    if (!typeMap[qr.type]) typeMap[qr.type] = { total: 0, count: 0, label: qr.typeLabel ?? qr.type };
    typeMap[qr.type].total += qr.score;
    typeMap[qr.type].count += 1;
  }
  return Object.entries(typeMap)
    .map(([type, d]) => ({ type, label: d.label, avgScore: Math.round(d.total / d.count) }))
    .filter(t => t.avgScore < 70)
    .sort((a, b) => a.avgScore - b.avgScore);
}
注意： 如果 InterviewRecord 中尚无 questionResults 字段，需要：
- 在 shared.tsx 的 InterviewRecord 接口中添加 questionResults?: QuestionResult[]
- 在 server/index.ts 的 POST /api/records 和 GET /api/records/:id 中对应补充数据写入和读取
