        {{ all: '全部', live: '实时', mock: '模拟' }[m]}
      </button>
    ))}
  </div>
  <select
    className="filter-select"
    value={filterPosition}
    onChange={e => setFilterPosition(e.target.value)}
  >
    <option value="all">所有岗位</option>
    {positions.map(p => (
      <option key={p.id} value={p.id}>{p.title}</option>
    ))}
  </select>
</div>

// 过滤逻辑（纯前端计算，无需 API）
const filteredRecords = interviewRecords.filter(r => {
  const modeMatch = filterMode === 'all' || r.mode === filterMode;
  const posMatch = filterPosition === 'all' || r.positionId === filterPosition;
  return modeMatch && posMatch;
});
